content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-010

=== 用户原始指令 (query.txt) ===
弄个今日专注时长卡片，那个小时数会变，点进去能看每日明细

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个今日专注时长卡片，那个小时数会变，点进去能看每日明细",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "focus": {
        "today": {
          "hoursText": {
            "type": "string",
            "description": "今日累计专注时长的小时数展示文本，会随统计结果变化。",
            "sampleValue": "3.3"
          },
          "updatedText": {
            "type": "string",
            "description": "今日专注数据的最近更新时间展示文本。",
            "sampleValue": "今日 18:20"
          },
          "focusedMinutes": {
            "type": "number",
            "description": "今日累计专注分钟数，用于专注目标进度展示。",
            "sampleValue": 200
          },
          "goalMinutes": {
            "type": "number",
            "description": "今日专注目标分钟数，用于进度条总量。",
            "sampleValue": 240
          },
          "remainText": {
            "type": "string",
            "description": "距离今日专注目标的剩余时长提示。",
            "sampleValue": "离目标还差 40 分钟"
          }
        },
        "detail": {
          "entryTitleText": {
            "type": "string",
            "description": "每日专注明细入口的标题文本。",
            "sampleValue": "每日明细"
          },
          "entryHintText": {
            "type": "string",
            "description": "进入每日专注明细后可查看内容的短提示。",
            "sampleValue": "按天查看趋势"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式图标，适合用于今日专注时长卡片的场景识别和视觉锚点。"
    }
  ]
}

