es":{"width":42,"height":24,"fontSize":16,"fontWeight":600,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none"}},{"id":"progress_bar","component":"Progress","value":"{{ ${/data/focus/today/focusedMinutes} }}","total":"{{ ${/data/focus/today/goalMinutes} }}","styles":{"width":160,"height":8,"type":"capsule","color":"#ffffffff"}},{"id":"remain_text","component":"Text","content":"{{ ${/data/focus/today/remainText} }}","styles":{"width":160,"height":16,"fontSize":12,"fontWeight":400,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none"}},{"id":"detail_panel","component":"Column","children":["detail_title","detail_hint","action_button"],"itemMargin":4,"styles":{"width":104,"height":84,"padding":6,"borderRadius":16,"backgroundColor":"#19ffffff","justifyContent":"start","alignItems":"start"}},{"id":"detail_title","component":"Text","content":"{{ ${/data/focus/detail/entryTitleText} }}","styles":{"width":92,"height":16,"fontSize":14,"fontWeight":700,"fontColor":"#ffffffff","maxLines":1,"textOverflow":"none"}},{"id":"detail_hint","component":"Text","content":"{{ ${/data/focus/detail/entryHintText} }}","styles":{"width":92,"height":14,"fontSize":12,"fontWeight":400,"fontColor":"#99ffffff","maxLines":1,"textOverflow":"none"}},{"id":"action_button","component":"Button","label":"看明细","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"com.huawei.hmos.settings","abilityName":"com.huawei.hmos.settings.MainAbility","uri":"intelligent_scene_entry"}}],"styles":{"width":92,"height":32,"borderRadius":16,"backgroundColor":"#19ffffff","fontSize":14,"fontWeight":500,"fontColor":"#ffffffff"}}]}}
